// ── 68. The Forgotten Contributors ────────────────────────────────────────────
const s68: SlotSpec = {
  n: 68,
  storyType: "player-story",
  build(a) {
    const sv = servers(a);
    const seasons = new Map(sv.rows.map((r) => [r.name, r]));
    const runSql = `SELECT pl.name, SUM(d.batter_runs) runs, SUM(CASE WHEN d.is_wide = 0 THEN 1 ELSE 0 END) balls FROM deliveries d JOIN innings i ON i.innings_id = d.innings_id JOIN players pl ON pl.player_id = d.batter_id WHERE ${REGULATION} AND i.batting_team_id IN ${a.T} GROUP BY pl.name`;
    const wkSql = `SELECT pl.name, COUNT(*) wk FROM dismissals x JOIN deliveries d ON d.delivery_id = x.delivery_id JOIN innings i ON i.innings_id = d.innings_id JOIN players pl ON pl.player_id = d.bowler_id WHERE ${REGULATION} AND i.bowling_team_id IN ${a.T} AND x.kind NOT IN ('run out', 'retired hurt', 'retired out', 'obstructing the field') GROUP BY pl.name`;
    const short = (n: string) => (seasons.get(n)?.seasons ?? 99) <= 2;
    const r = a.rows<{ name: string; runs: number; balls: number }>(runSql).filter((x) => short(x.name)).sort((x, y) => y.runs - x.runs);
    const w = a.rows<{ name: string; wk: number }>(wkSql).filter((x) => short(x.name)).sort((x, y) => y.wk - x.wk);
    a.table("fc-runs", `${a.code} leading run-scorers who played two seasons or fewer`, "Regulation innings", r.length, "players", runSql, r.slice(0, 8).map((x) => ({ player: `${x.name} (${seasons.get(x.name)!.first === seasons.get(x.name)!.last ? seasons.get(x.name)!.first : `${seasons.get(x.name)!.first}–${seasons.get(x.name)!.last}`})`, runs: x.runs })));
    const tok = {
      r1: a.text("fc-r1", r[0].name, `Leading ${a.code} run-scorer with two seasons or fewer at the franchise`, { filters: "Regulation innings", n: r.length, nUnit: "players", sql: runSql, check: derived("max") }),
      r1n: a.int("fc-r1n", r[0].runs, "Runs by that player for the franchise", { unit: "runs", filters: "Regulation innings", n: r[0].balls, nUnit: "balls", sql: runSql, check: range(r[0].runs, 100, 1500, "runs") }),
      w1: a.text("fc-w1", w[0].name, `Leading ${a.code} wicket-taker with two seasons or fewer at the franchise`, { filters: "Bowler-credited", n: w.length, nUnit: "players", sql: wkSql, check: derived("max") }),
      w1n: a.int("fc-w1n", w[0].wk, "Wickets by that player for the franchise", { unit: "wickets", filters: "Bowler-credited", n: w[0].wk, nUnit: "wickets", sql: wkSql, check: range(w[0].wk, 5, 60, "wickets") }),
      n: a.int("fc-n", sv.rows.filter((x) => x.seasons <= 2).length, `Players with two seasons or fewer at ${a.code}`, { filters: span(a), n: sv.rows.length, nUnit: "players", sql: sv.sql, check: derived("count") }),
    };
    return {
      dek: `Franchise histories are told through long-serving stars. The players who passed through ${a.name} in a season or two, and still left a mark, are easier to forget.`,
      excerpt: `${r[0].name} and ${w[0].name} each made a substantial contribution to ${a.name} in two seasons or fewer. Short stays like theirs fill in the parts of the history the headlines skip.`,
      keyTakeaways: [
        `${tok.n} players have batted or bowled for ${a.code} in two seasons or fewer.`,
        `Among them, ${tok.r1} scored the most runs (${tok.r1n}).`,
        `${tok.w1} took the most wickets (${tok.w1n}).`,
      ],
      sections: [
        { heading: "Beyond the Headlines", body: [
          `Franchise histories are usually told through the players who stayed longest. But every season also depends on short-stay contributors who arrive, perform and move on.`,
          `${tok.n} players have batted or bowled for ${a.name} in two seasons or fewer.`,
        ] },
        { heading: "Short Stays, Real Contributions", body: [
          `Among them, ${tok.r1} scored the most runs, ${tok.r1n}. The chart lists the leading run-scorers among short-stay players.`,
          `With the ball, ${tok.w1} took the most wickets among them, ${tok.w1n}.`,
        ], chartIds: ["fc-chart"] },
        { heading: "Why They Are Forgotten", body: [
          `Short-stay players rarely become the faces of a franchise, whatever they contribute. Public memory follows tenure and captaincy more than output.`,
          `{{hyp:forgotten}}`,
        ] },
        { heading: "Counting, Not Ranking", body: [
          `Runs and wickets reward opportunity: a player who batted more scored more. This article lists contributions, not a judgement of who was best.`,
          `The salary-versus-contribution model elsewhere in this series weighs contributions against opportunity.`,
        ] },
        { heading: "CricField Verdict: Credit the Passers-Through", body: [
          `${a.poss} history includes real contributions from players who stayed only briefly. ${r[0].name} and ${w[0].name} are the leading examples.`,
          `A full history should include them.`,
        ] },
      ],
      charts: [{ id: "fc-chart", type: "bar", title: "Short-stay run-scorers", subtitle: `${a.code}, players with two seasons or fewer`, table: "fc-runs", xKey: "player", series: [{ key: "runs", label: "Runs" }], unit: "runs", takeaway: "Several short-stay players made substantial contributions.", ariaLabel: `Horizontal bar chart of runs scored for ${a.code} by players who stayed two seasons or fewer.` }],
      hypotheses: [hyp("forgotten", "fan recall of former players tracks seasons at the franchise more closely than runs or wickets contributed.", "No fan recall data is available.", "Survey fans on recognition of former players and compare with tenure and output.")],
      players: [r[0].name, w[0].name],
      seasons: [span(a)],
      hero: { narrative: `${r[0].name} for ${a.name}.`, wanted: `${r[0].name} batting for ${a.name}.`, query: `${r[0].name} ${a.name}` },
      related: [43, 53, 70],
      seo: { metaTitle: metaTitle(`The forgotten contributors of ${a.code}`), metaDescription: metaDesc(`The players who passed through ${a.name} in a season or two and still made a substantial contribution.`) },
      methodology: `${METHOD} Short stay = batted or bowled for the franchise in two seasons or fewer. Wickets are bowler-credited.`,
    };
  },
};

// ── 69. The Turning-Point Audit ───────────────────────────────────────────────
const s69: SlotSpec = {
  n: 69,
  storyType: "investigation",
  build(a) {
    const sr = seasonRecord(a, "tp");
    const best = [...sr.rows].sort((x, y) => (y.winPct as number) - (x.winPct as number)).slice(0, 3).map((r) => Number(r.season));
    const measures = [
      { id: "ppbat", label: "Powerplay batting", side: "bat" as const, o: [0, 5], better: 1 },
      { id: "midbat", label: "Middle-overs batting", side: "bat" as const, o: [6, 14], better: 1 },
      { id: "deathbat", label: "Death batting", side: "bat" as const, o: [15, 19], better: 1 },
      { id: "ppbowl", label: "Powerplay bowling", side: "bowl" as const, o: [0, 5], better: -1 },
      { id: "midbowl", label: "Middle-overs bowling", side: "bowl" as const, o: [6, 14], better: -1 },
      { id: "deathbowl", label: "Death bowling", side: "bowl" as const, o: [15, 19], better: -1 },
    ];
    const out = measures.map((m) => {
      const s = a.rateSeries(m.side, m.o[0], m.o[1]);
      const rel = (ys: (r: { year: number }) => boolean) => mean(s.rows.filter(ys).map((r) => r.team - r.league));
      const b = rel((r) => best.includes(r.year)), o = rel((r) => !best.includes(r.year));
      return { ...m, b, o, gain: (b - o) * m.better, sql: s.sql };
    });
    a.table("tp-cmp", `${a.code} best three seasons vs the rest, relative to the league`, `Runs per over relative to the league; best seasons: ${best.join(", ")}`, sr.rows.length, "seasons", out[0].sql, out.map((m) => ({ measure: m.label, bestSeasons: dp(m.b, 2), otherSeasons: dp(m.o, 2), advantage: dp(m.gain, 2) })));
    const top = [...out].sort((x, y) => y.gain - x.gain)[0];
    const tok = {
      best: a.text("tp-best", best.slice().sort().join(", "), `${a.poss} three best seasons by win rate`, { filters: "Season table", n: sr.rows.length, nUnit: "seasons", sql: "season table", check: derived("top three") }),
      top: a.text("tp-top", top.label.toLowerCase(), "Measure with the largest advantage in the best seasons", { filters: "Relative to league, best minus other seasons", n: sr.rows.length, nUnit: "seasons", sql: top.sql, check: derived("max over six measures") }),
      gain: a.num("tp-gain", top.gain, "Size of that advantage", { unit: "runs per over", filters: "As above", n: sr.rows.length, nUnit: "seasons", sql: top.sql, check: range(top.gain, -5, 5, "runs per over") }, 2),
    };
    for (const m of out) tok[`g-${m.id}` as keyof typeof tok] = a.num(`tp-g-${m.id}`, m.gain, `${m.label}: advantage in the best seasons over the rest`, { unit: "runs per over", filters: "Relative to league", n: sr.rows.length, nUnit: "seasons", sql: m.sql, check: range(m.gain, -5, 5, "runs per over") }, 2);
    const T = tok as Record<string, string>;
    return {
      dek: `What actually changed when ${a.name} were at their best? Comparing their three best seasons with the rest, phase by phase, finds the turning points.`,
      excerpt: `In ${a.poss} best seasons, the biggest improvement relative to the league came in ${top.label.toLowerCase()}. That is where the turning points in their history were made.`,
      keyTakeaways: [
        `${a.poss} three best seasons by win rate were ${tok.best}.`,
        `The largest advantage in those seasons, relative to the league, came in ${tok.top}: ${tok.gain} runs an over better than in other seasons.`,
        `Each of the six phase measures is compared in the chart.`,
      ],
      sections: [
        { heading: "What Separates the Best Seasons", body: [
          `Good seasons are remembered for players and moments. An audit asks a narrower question: in which part of the game were ${a.name} most improved, relative to the league, when they were at their best?`,
          `Their three best seasons by win rate were ${tok.best}. CricField compared them with all other seasons across six phases of batting and bowling.`,
        ] },
        { heading: "The Turning Point", body: [
          `The largest advantage came in ${tok.top}: ${tok.gain} runs an over better, relative to the league, than in other seasons.`,
          `For the other phases: powerplay batting ${T["g-ppbat"]}, middle-overs batting ${T["g-midbat"]}, death batting ${T["g-deathbat"]}, powerplay bowling ${T["g-ppbowl"]}, middle-overs bowling ${T["g-midbowl"]} and death bowling ${T["g-deathbowl"]} runs an over (positive = better in the best seasons).`,
        ], chartIds: ["tp-chart"] },
        { heading: "Why It Matters", body: [
          `The phase that separated the best seasons is the phase most worth protecting in squad building.`,
          `{{hyp:turning}}`,
        ] },
        { heading: "Three Seasons Is a Small Sample", body: [
          `Comparing three seasons with the rest is a small-sample exercise; a single exceptional player can drive a whole phase. The finding is a pointer, not a law.`,
          `Repeating the audit with the best five seasons would test whether it holds.`,
        ] },
        { heading: `CricField Verdict: ${top.label} Made the Difference`, body: [
          `${a.poss} best seasons were defined most by ${top.label.toLowerCase()}.`,
          `Future squads should treat that phase as the franchise's proven route to success.`,
        ] },
      ],
      charts: [{ id: "tp-chart", type: "bar", title: "Advantage in the best seasons", subtitle: `${a.code}: best three seasons minus the rest, relative to the league`, table: "tp-cmp", xKey: "measure", series: [{ key: "advantage", label: "Advantage" }], unit: "runs per over", takeaway: `${top.label} improved most in the best seasons.`, ariaLabel: `Horizontal bar chart of how much better ${a.code} were in each phase in their best three seasons than in other seasons.` }],
      hypotheses: [hyp("turning", `${top.label.toLowerCase()} also separates ${a.poss} playoff seasons from non-playoff seasons, not only the best three.`, "Only the best three seasons were compared.", "Repeat the comparison for playoff and non-playoff seasons.")],
      players: [],
      seasons: [span(a)],
      hero: { narrative: `${a.name} at their best.`, wanted: `${a.name} celebrating a win.`, query: `${a.name} celebrate win` },
      related: [62, 63, 91],
      seo: { metaTitle: metaTitle(`The turning-point audit: what changed in ${a.poss} best seasons`), metaDescription: metaDesc(`${a.poss} three best seasons compared with the rest, phase by phase, to find what really changed.`) },
      methodology: `${METHOD} Each phase is measured as runs per over relative to the league in the same season; advantage = best-season average minus other-season average, signed so that positive is better.`,
    };
  },
};

// ── 70. Legacy Versus Recency ─────────────────────────────────────────────────
const s70: SlotSpec = {
  n: 70,
  storyType: "investigation",
  build(a) {
    const bSql = `SELECT ${YEAR()} year, pl.name, f.runs, f.balls_faced balls FROM fact_batting_innings f JOIN innings i ON i.innings_id = f.innings_id JOIN matches m ON m.match_id = i.match_id JOIN players pl ON pl.player_id = f.striker_id WHERE i.innings_number <= 2 AND i.batting_team_id IN ${a.T} ORDER BY f.runs DESC, f.balls_faced`;
    const wSql = `SELECT ${YEAR()} year, pl.name, f.wickets, f.runs_conceded runs FROM fact_bowling_spells f JOIN innings i ON i.innings_id = f.innings_id JOIN matches m ON m.match_id = i.match_id JOIN players pl ON pl.player_id = f.bowler_id WHERE i.innings_number <= 2 AND i.bowling_team_id IN ${a.T} ORDER BY f.wickets DESC, f.runs_conceded`;
    const bat = a.rows<{ year: number; name: string; runs: number; balls: number }>(bSql);
    const bowl = a.rows<{ year: number; name: string; wickets: number; runs: number }>(wSql);
    const top = bat.slice(0, 10);
    a.table("lr-top", `${a.poss} highest individual innings`, "Regulation innings", bat.length, "innings", bSql, top.map((r) => ({ innings: `${r.name}, ${r.year}`, runs: r.runs, balls: r.balls })));
    const recent = (y: number) => y >= 2024;
    const topRecent = top.filter((r) => recent(r.year)).length;
    const allRecent = pctOf(bat.filter((r) => recent(r.year)).length, bat.length);
    const topBowl = bowl.slice(0, 10);
    const bowlRecent = topBowl.filter((r) => recent(r.year)).length;
    const allBowlRecent = pctOf(bowl.filter((r) => recent(r.year)).length, bowl.length);
    const tok = {
      best: a.text("lr-best", `${top[0].name}'s ${top[0].runs} in ${top[0].year}`, `${a.poss} highest individual innings`, { filters: "Regulation innings", n: bat.length, nUnit: "innings", sql: bSql, check: derived("max") }),
      bowlBest: a.text("lr-bowl", `${topBowl[0].name}'s ${topBowl[0].wickets} for ${topBowl[0].runs} in ${topBowl[0].year}`, `${a.poss} best bowling figures`, { filters: "Regulation innings", n: bowl.length, nUnit: "spells", sql: wSql, check: derived("max wickets, then fewest runs") }),
      topRecent: a.text("lr-top-recent", words[topRecent], "Top-ten innings from 2024–2026", { filters: "Regulation innings", n: 10, nUnit: "innings", sql: bSql, check: derived("count") }),
      allRecent: a.pct("lr-all-recent", allRecent, `Share of all ${a.code} innings played in 2024–2026`, { filters: "Regulation innings", n: bat.length, nUnit: "innings", sql: bSql, check: floor(bat.length, 100, "innings") }, 0),
      bowlRecent: a.text("lr-bowl-recent", words[bowlRecent], "Top-ten bowling spells from 2024–2026", { filters: "Regulation innings", n: 10, nUnit: "spells", sql: wSql, check: derived("count") }),
      allBowlRecent: a.pct("lr-allb-recent", allBowlRecent, `Share of all ${a.code} bowling spells in 2024–2026`, { filters: "Regulation innings", n: bowl.length, nUnit: "spells", sql: wSql, check: floor(bowl.length, 100, "spells") }, 0),
    };
    const batSkew = topRecent * 10 - allRecent > 10;
    return {
      dek: `Ranking ${a.poss} greatest performances means weighing old classics against recent fireworks. Scoring has risen, so raw numbers favour the present.`,
      excerpt: `${a.poss} highest innings is ${tok.best}. Seasons since 2024 ${batSkew ? "are over-represented" : "are not over-represented"} among their top ten innings, a test of how much recency bias raw rankings carry.`,
      keyTakeaways: [
        `${a.poss} highest individual innings is ${tok.best}; their best bowling figures are ${tok.bowlBest}.`,
        `Of their top ten innings, ${tok.topRecent} came in 2024–2026, seasons that account for ${tok.allRecent} of all their innings.`,
        `Of their top ten bowling spells, ${tok.bowlRecent} came in 2024–2026, against ${tok.allBowlRecent} of all spells.`,
      ],
      sections: [
        { heading: "Legacy and Recency", body: [
          `Every list of a franchise's greatest performances has to decide how to weigh old and new. Recent performances are vivid; older ones carry history.`,
          `By raw numbers, ${a.poss} highest individual innings is ${tok.best} and their best bowling figures are ${tok.bowlBest}.`,
        ] },
        { heading: "The Raw Ranking", body: [
          `The chart lists ${a.poss} ten highest individual innings. ${tok.topRecent} of them came in 2024–2026, seasons that account for ${tok.allRecent} of all the franchise's innings.`,
          batSkew ? `Recent seasons are over-represented in the top ten, which is what the league-wide rise in scoring would predict.` : `Recent seasons are not over-represented in the top ten, despite the league-wide rise in scoring.`,
        ], chartIds: ["lr-chart"] },
        { heading: "Bowling Runs the Other Way", body: [
          `With the ball, ${tok.bowlRecent} of the top ten spells by wickets came in 2024–2026, against ${tok.allBowlRecent} of all spells. Higher scoring makes great bowling figures harder to achieve.`,
          `{{hyp:adjust}}`,
        ] },
        { heading: "A Fairer Ranking", body: [
          `A fairer ranking would express each performance relative to the scoring in its season, so that a century in a low-scoring year counts for more than one in a high-scoring year.`,
          `The venue-adjusted rating elsewhere in this series applies that idea to players.`,
        ] },
        { heading: "CricField Verdict: Adjust Before You Rank", body: [
          `Raw rankings of ${a.poss} greatest innings ${batSkew ? "lean towards recent seasons" : "do not lean heavily towards recent seasons"}.`,
          `Any definitive list should adjust for each season's scoring before comparing eras.`,
        ] },
      ],
      charts: [{ id: "lr-chart", type: "bar", title: "Highest individual innings", subtitle: `${a.code}, all seasons`, table: "lr-top", xKey: "innings", series: [{ key: "runs", label: "Runs" }], unit: "runs", takeaway: "The raw ranking mixes eras with very different scoring levels.", ariaLabel: `Horizontal bar chart of the ten highest individual innings for ${a.code}.` }],
      hypotheses: [hyp("adjust", `ranking ${a.poss} innings relative to each season's average strike rate would move several pre-2018 innings into the top ten.`, "Season-adjusted rankings have not been computed.", "Divide each innings' runs and strike rate by the season average and re-rank.")],
      players: [top[0].name, topBowl[0].name],
      seasons: [span(a)],
      hero: { narrative: `${top[0].name}'s great innings for ${a.name}.`, wanted: `${top[0].name} batting for ${a.name}.`, query: `${top[0].name} ${a.name} century` },
      related: [83, 68, 62],
      seo: { metaTitle: metaTitle(`Legacy versus recency: ranking ${a.poss} greatest performances`), metaDescription: metaDesc(`${a.poss} highest innings and best bowling figures, and how much recency bias raw rankings carry.`) },
      methodology: `${METHOD} Innings and spells from the warehouse fact tables. Recent = 2024–2026.`,
    };
  },
};

